        aggregator_spec = make_aggregator_spec_adj_lines_merge()
        parallelizer_cc_seq_adjm = make_parallelizer_consec_chunks(aggregator_spec=aggregator_spec)
        self.append_to_parallelizer_list(parallelizer_cc_seq_adjm)

